      "answerText": "(B) Glutamate and aspartate",
      "explanation": "The final step in the blood coagulation cascade is the conversion of the soluble plasma protein fibrinogen into insoluble fibrin, which forms the meshwork of the clot. This conversion is catalyzed by the enzyme thrombin. Fibrinogen is a large protein composed of three pairs of polypeptide chains. The central domain of the molecule contains several short peptide sequences called fibrinopeptides A and B. These fibrinopeptides are highly enriched in the acidic amino acids, aspartate and glutamate. These amino acids have negatively charged carboxyl groups in their side chains at physiological pH. This high concentration of negative charge in the central domain of fibrinogen causes electrostatic repulsion between fibrinogen molecules, keeping them soluble and preventing spontaneous aggregation. Thrombin works by cleaving off these negatively charged fibrinopeptides, which exposes polymerization sites and allows the fibrin monomers to aggregate into an insoluble fibrin clot.",
