      "explanation": "Allosteric inhibition occurs when a molecule binds to an enzyme at a site other than the active site (the allosteric site), causing a change in the enzyme’s conformation and reducing its activity.\nIn this case, Alanine acts as an allosteric inhibitor of Pyruvate kinase. When alanine levels are high, it signals that the cell has sufficient energy and building blocks, thereby inhibiting pyruvate kinase and slowing down glycolysis.\nOther options do not represent classical allosteric inhibition:\n(A) Malonic acid inhibits succinate dehydrogenase competitively, not allosterically.\n(B) 2,3-BPG affects hemoglobin oxygen binding, but this is cooperative binding, not enzyme inhibition.\n(D) Pepsin is an enzyme digesting proteins; no allosteric inhibition is described here.\nHence, the correct example of allosteric inhibition is (C) Amino acid alanine & pyruvate kinase.",
