      "explanation": "Severe burns can lead to stress ulcers due to hypovolemia, reduced gastric mucosal perfusion, and increased gastric acid secretion. These ulcers are most commonly found in the Stomach, particularly in the body and fundus.\nPatients may present with melena (black stools), hypotension, and anemia from gastrointestinal bleeding, as described in this case. Curling ulcers can develop within 24–72 hours after a major burn and may contribute to significant morbidity and mortality if not recognized.\nOther options:\n1. Duodenum : Less commonly involved in burn-induced stress ulcers.\n2. Esophagus : Rarely affected by stress ulcers.\n3. Ileum : Not typically involved in stress-related ulceration.\nHence, in burn patients with gastrointestinal bleeding, the stomach is the organ most likely affected.",
