      "correct": "D",
      "answerText": "(D) All of the above",
      "explanation": "Cardiogenic shock occurs when the heart is unable to pump sufficient blood to meet the body’s metabolic demands, resulting in severe hypotension and tissue hypoperfusion. Although myocardial infarction (MI) is the most common cause, several mechanical and functional cardiac conditions can also produce shock without primary infarction. Acute mitral regurgitation leads to sudden backflow of blood from the left ventricle into the left atrium, causing pulmonary congestion and reduced forward cardiac output. Ventricular septal rupture creates an abnormal left-to-right shunt, decreasing effective systemic perfusion and overloading the pulmonary circulation. Isolated right ventricular failure or shock impairs blood flow to the lungs and subsequently reduces left ventricular filling, lowering systemic output. Each of these conditions can independently result in profound circulatory collapse. Therefore, all listed options are recognized non-infarction causes of cardiogenic shock.",
