      "correct": "B",
      "answerText": "(B) Study of diseases",
      "explanation": "Pathology is the branch of medical science that deals with the study of diseases, including their causes, development, structural changes, and effects on the body. It forms the scientific foundation of modern medicine by helping clinicians understand how normal physiological processes are altered in disease states. Pathologists examine tissues, cells, body fluids, and organs using laboratory techniques such as microscopy, molecular testing, and biochemical analysis to diagnose diseases and determine their severity. The field is broadly divided into anatomical pathology (study of structural changes in tissues and organs) and clinical pathology (laboratory analysis of blood, urine, and other body fluids). The word “pathology” originates from Greek roots: pathos meaning suffering or disease, and logos meaning study. Therefore, the term literally translates to the study of disease processes, making option B the correct answer.",
