      "answerText": "(B) 10 mg/kg/day",
      "explanation": "The physiological dose of hydrocortisone refers to the amount required to replace the body's normal daily production of cortisol. This replacement dose is crucial in managing conditions like congenital adrenal hyperplasia or adrenal insufficiency. The normal endogenous cortisol production rate is approximately 5-10 mg/m²/day. When converting this to a dose based on body weight for children, the widely accepted physiological replacement dose of hydrocortisone is in the range of 8-15 mg/m²/day, which corresponds to approximately 10-15 mg/kg/day in infants and young children, divided into three daily doses to mimic the natural diurnal rhythm of cortisol secretion. The value of 10 mg/kg/day falls within this standard therapeutic range and is a commonly cited figure for physiological replacement. Doses higher than this are considered supraphysiological or pharmacological and are used for their anti-inflammatory or immunosuppressive effects. The other options represent doses that are either too low or too high for standard physiological replacement in a pediatric context, where weight-based dosing is most common.",
