      "answerText": "(B) Risedronate",
      "explanation": "Risedronate reduces bone breakdown in osteoporosis by inhibiting osteoclast activity. Osteoporosis is characterized by an imbalance between bone resorption (breakdown) and bone formation, leading to fragile bones and increased fracture risk. Osteoclasts are the cells responsible for bone resorption. Risedronate belongs to a class of drugs called bisphosphonates, which bind strongly to bone mineral and suppress osteoclast-mediated bone destruction. As a result, bone density increases and fracture risk decreases.\nTeriparatide (A) works differently; it is a recombinant form of parathyroid hormone that stimulates new bone formation by activating osteoblasts, so it promotes bone building rather than reducing breakdown. Cortisone (C) actually worsens osteoporosis because long-term corticosteroid use accelerates bone loss and decreases calcium absorption. Cimetidine (D) is an H₂-receptor antagonist used for peptic ulcer disease and has no significant role in bone metabolism.\nTherefore, among the given options, risedronate is the medication specifically designed to reduce bone resorption and slow the progression of osteoporosis.",
