      "number": 109,
      "statement": "Besides epinephrine, which medication is recommended for ventricular fibrillation during cardiac arrest?",
      "options": [
        "Amiodarone",
        "Dopamine",
        "Adenosine",
        "Atropine"
      ],
      "correct": "A",
      "answerText": "(A) Amiodarone",
      "explanation": "Amiodarone is recommended, in addition to epinephrine, for the treatment of ventricular fibrillation (VF) or pulseless ventricular tachycardia during cardiac arrest that is unresponsive to defibrillation. VF is a life-threatening arrhythmia characterized by chaotic electrical activity in the ventricles, resulting in no effective cardiac output. Amiodarone is a class III antiarrhythmic drug that prolongs the cardiac action potential and refractory period, helping to stabilize the cardiac membrane and restore a normal rhythm.\nDopamine (B) is mainly used for hemodynamic support in shock and severe hypotension, not for VF during arrest. Adenosine (C) is used to treat certain supraventricular tachycardias, not ventricular fibrillation. Atropine (D) is used for symptomatic bradycardia and is no longer recommended for asystole or pulseless electrical activity in cardiac arrest protocols.\nTherefore, amiodarone is the preferred antiarrhythmic medication for shock-refractory ventricular fibrillation during cardiac arrest.",
