      "explanation": "Vitamin K is a fat-soluble vitamin essential for the synthesis of clotting factors II, VII, IX, and X in the liver, as well as proteins C and S. It plays a crucial role in blood coagulation, promoting clot formation rather than preventing it. Therefore, option (A) is incorrect because vitamin K is not an anticoagulant; instead, it has a procoagulant effect.\nA significant portion of vitamin K (especially vitamin K₂) is produced by normal intestinal bacteria. Prolonged use of broad-spectrum antimicrobials can disrupt gut flora, reducing endogenous vitamin K production and potentially leading to deficiency. This deficiency may result in bleeding tendencies due to impaired clotting factor synthesis, making option (B) correct.\nOption (C) is incorrect because the daily dietary requirement of vitamin K is in micrograms (about 55–120 µg/day for adults), not milligrams. Since statements (A) and (C) are false, option (D) cannot be correct.\nThus, prolonged antimicrobial therapy is a recognized cause of vitamin K deficiency.",
