      "answerText": "(A) Brain",
      "explanation": "Putrefaction is the decomposition of body tissues by the action of anaerobic bacteria, primarily those originating from the gastrointestinal tract. The rate at which different organs putrefy depends on factors like their water content, vascularity, and proximity to bacterial sources. The first external sign of putrefaction is a greenish discoloration of the skin over the right iliac fossa, due to the cecum's proximity to the abdominal wall. Internally, organs that are rich in fluid and enzymes decompose more rapidly. The larynx and trachea are often cited as the first internal organs to show putrefactive changes. Following this, the brain (especially in infants), stomach, intestines, and spleen decompose quickly.  Organs like the heart , kidneys, and lungs decompose at an intermediate rate. The last organs to putrefy are typically the prostate  in males and the non-gravid uterus in females, due to their dense, fibrous muscular structure.",
