      "number": 121,
      "statement": "What characteristic odor is associated with a mummified body?",
      "options": [
        "Odourless",
        "Putrid",
        "Pungent",
        "Offensive"
      ],
      "correct": "A",
      "answerText": "(A) Odourless",
      "explanation": "Mummification is a modification of putrefaction that occurs in dry environments, either hot or cold, with good air circulation. In these conditions, the body tissues undergo rapid dehydration before decompositional bacteria can proliferate. The skin becomes dry, leathery, and brown-black, and it adheres closely to the underlying bones. Because the putrefactive process is arrested due to the lack of moisture, the characteristic foul, offensive, and putrid odors associated with decomposition do not develop.  Instead, a mummified body is essentially odourless or may have a faint, dry, or dusty smell.  This lack of odor is a key feature that distinguishes mummification from typical putrefaction. The internal organs also dry out and shrivel, and the body can be preserved for a very long time in this state. The smell is not pungent, which would imply a sharp, strong smell.",
