      "correct": "A",
      "answerText": "(A) Varicella-zoster",
      "explanation": "Shingles, also known as herpes zoster, is a viral disease characterized by a painful skin rash with blisters, typically appearing in a limited area on one side of the body (a dermatome). It is caused by the reactivation of the Varicella-Zoster Virus (VZV).  VZV is the same virus that causes chickenpox (varicella) as a primary infection, usually in childhood. After the primary infection resolves, the virus does not get eliminated from the body but instead becomes dormant, establishing a latent infection in the nerve cell bodies of the dorsal root ganglia, cranial nerve ganglia, or autonomic ganglia. Years or decades later, if the immune system weakens due to age, stress, or immunosuppression, the virus can reactivate. It then travels down the sensory nerve axons to the skin supplied by that nerve, causing the characteristic unilateral, dermatomal rash of shingles. Herpes simplex virus causes cold sores or genital herpes.  CMV is another herpesvirus that causes different pathologies.",
