      "explanation": "The Sabin-Feldman dye test is the gold standard serological test for the diagnosis of toxoplasmosis, an infection caused by the protozoan parasite Toxoplasma gondii.  This test is a neutralization assay that detects the presence of specific IgG antibodies to Toxoplasma in a patient's serum. The principle of the test is that live, laboratory-maintained Toxoplasma tachyzoites are incubated with the patient's serum. If specific antibodies are present in the serum, they will bind to the surface of the parasites and, in the presence of complement (which is also added), will cause the parasite's cell membrane to lyse. When a dye, such as methylene blue, is added, the lysed (dead) parasites will not take up the dye and will appear as unstained ghosts. In contrast, if no antibodies are present, the parasites will remain viable and will stain blue. A high titer of antibodies indicates infection.",
