      "correct": "A",
      "answerText": "(A) Dog",
      "explanation": "Echinococcus granulosus is a cestode (tapeworm) that causes cystic echinococcosis (hydatid disease) in humans. The parasite has a complex two-host lifecycle. The definitive host, where the adult tapeworm lives in the intestine, is a canid, most commonly the dog.  The adult worm in the dog's intestine produces eggs, which are passed in the feces. The intermediate hosts are typically herbivores, such as sheep, goats, cattle, and pigs, which become infected by ingesting the eggs. In the intermediate host, the eggs hatch, and the larvae migrate to organs like the liver and lungs, where they form the characteristic hydatid cysts. The lifecycle is completed when a dog ingests the cyst-containing organs of an infected intermediate host. Humans are accidental intermediate hosts, becoming infected by ingesting the eggs from soil or food contaminated with dog feces, or through direct contact with infected dogs. Cats are definitive hosts for other tapeworms like Taenia taeniaeformis.",
