      "correct": "B",
      "answerText": "(B) IGRA (Interferon-Gamma Release Assay)",
      "explanation": "The Interferon-Gamma Release Assay (IGRA) is a blood test used to diagnose latent tuberculosis infection. The principle of the test is to measure the cell-mediated immune response to Mycobacterium tuberculosis antigens. To do this, a sample of whole blood containing the patient's T-lymphocytes is required.  The blood is incubated in tubes containing specific MTB antigens (such as ESAT-6 and CFP-10). If the patient's T-cells have been previously sensitized to these antigens (i.e., the patient has a TB infection), they will be stimulated to produce and release Interferon-gamma (IFN-γ). The amount of IFN-γ released is then measured, typically by an ELISA method. Bacterial culture for sepsis also uses blood, but it is inoculated into special culture media.  GeneXpert is typically performed on sputum or other tissue samples.  Viral serology is performed on serum or plasma, not whole blood.",
