      "explanation": "Sydenham's chorea is a major neurological manifestation of acute rheumatic fever, resulting from an autoimmune reaction involving the basal ganglia. It presents with choreiform (rapid, involuntary, purposeless) movements, emotional lability, and hypotonia. While many cases are self-limiting, severe or intractable chorea requires pharmacological treatment. The current first-line treatment and drug of choice for Sydenham's chorea is sodium valproate. It has been shown to be effective in controlling the abnormal movements and has a more favorable safety profile compared to older agents. Haloperidol, a dopamine D2 receptor antagonist, is also effective but is now considered a second-line option due to the higher risk of acute extrapyramidal side effects and the potential for long-term tardive dyskinesia. Risperidone, an atypical antipsychotic, may also be used. Warfarin is an anticoagulant and is not used to treat the chorea itself.",
