      "correct": "B",
      "answerText": "(B) Achalasia cardia",
      "explanation": "Achalasia cardia is a primary esophageal motility disorder characterized by two key features : impaired relaxation of the lower esophageal sphincter (LES) upon swallowing and the absence of normal peristalsis in the body of the esophagus. This leads to a functional obstruction at the gastroesophageal junction, causing symptoms like dysphagia (difficulty swallowing), regurgitation, and chest pain. The Heller myotomy is the standard surgical treatment for achalasia. The procedure involves making a longitudinal incision through the muscle layers (myotomy) of the distal esophagus and the proximal stomach, specifically cutting through the hypertonic lower esophageal sphincter muscle. This relieves the obstruction and allows food to pass more easily into the stomach. The procedure is usually performed laparoscopically and is often combined with an anti-reflux procedure (fundoplication) to prevent postoperative gastroesophageal reflux. Zenker's diverticulum is treated with a diverticulectomy and cricopharyngeal myotomy.",
