      "number": 161,
      "statement": "Which of the following conditions lead to hypokalemic metabolic alkalosis accompanied by hypertension?",
      "options": [
        "Liddle syndrome",
        "Bartter syndrome",
        "Gitelman syndrome",
        "Renal tubular acidosis"
      ],
      "correct": "A",
      "answerText": "(A) Liddle syndrome",
      "explanation": "The combination of hypokalemic metabolic alkalosis (low potassium, high bicarbonate) and hypertension is a key finding that points towards a state of mineralocorticoid excess or apparent mineralocorticoid excess. Liddle syndrome is a rare, autosomal dominant genetic disorder that perfectly fits this profile. It is caused by a gain-of-function mutation in the genes for the epithelial sodium channel (ENaC) in the collecting ducts of the kidney. This mutation leads to constitutive, unregulated reabsorption of sodium, independent of aldosterone. The excessive sodium reabsorption causes volume expansion and severe hypertension. It also creates a negative electrical potential in the tubular lumen, which drives the secretion and subsequent loss of potassium and hydrogen ions, resulting in hypokalemia and metabolic alkalosis. A key feature is that renin and aldosterone levels are suppressed. Bartter and Gitelman syndromes cause hypokalemic alkalosis but with normal or low blood pressure.",
