      "explanation": "The Global Initiative for Chronic Obstructive Lung Disease (GOLD) provides a framework for the diagnosis and management of Chronic Obstructive Pulmonary Disease (COPD). A key component of this is the classification of the severity of airflow limitation based on post-bronchodilator spirometry. The diagnosis of COPD requires a post-bronchodilator FEV1/FVC ratio of less than 0.70. Once diagnosed, the severity is graded based on the forced expiratory volume in one second (FEV1) as a percentage of the predicted normal value. The grades are :\n1. GOLD 1 (Mild) : FEV1 � 80% predicted\n2. GOLD 2 (Moderate) : 50% � FEV1 < 80% predicted\n3. GOLD 3 (Severe) : 30% � FEV1 < 50% predicted\n4. GOLD 4 (Very Severe) : FEV1 < 30% predicted\nTherefore, an FEV1 of less than 30% of the predicted normal value corresponds to Very Severe COPD according to the GOLD criteria.",
