      "correct": "C",
      "answerText": "(C) Subglottic stenosis",
      "explanation": "Oxygen therapy is beneficial in conditions where hypoxemia results from impaired gas exchange at the alveolar level. In asthma, oxygen helps correct hypoxia caused by bronchospasm and ventilation–perfusion mismatch. In pneumonia, alveoli are filled with inflammatory exudate, impairing oxygen diffusion, so supplemental oxygen improves arterial oxygenation. In pulmonary fibrosis, thickening of the alveolar membrane reduces diffusion capacity, and oxygen therapy increases the oxygen gradient, improving blood oxygen levels.\nHowever, subglottic stenosis is an upper airway obstruction located below the vocal cords. The primary issue is mechanical narrowing of the airway, not impaired oxygen diffusion. Simply giving oxygen does not relieve the obstruction. These patients require airway management such as nebulization, steroids, dilation, or possibly surgical intervention. While oxygen may be given temporarily, it does not correct the underlying problem.\nTherefore, the condition that may not significantly benefit from oxygen therapy is (C) Subglottic stenosis.",
