      "explanation": "In pregnancy, the goal of HIV treatment is to maintain maternal health and prevent vertical transmission to the fetus. Current guidelines recommend combination antiretroviral therapy (ART) consisting of two nucleoside reverse transcriptase inhibitors (NRTIs) plus a third agent, usually an integrase strand transfer inhibitor like dolutegravir.\nTenofovir disoproxil fumarate (TDF) with either emtricitabine (FTC) or lamivudine (3TC) are commonly used and considered safe in pregnancy. Abacavir with lamivudine is another acceptable NRTI backbone in women who are HLA-B5701 negative. Since all these NRTI combinations are acceptable when combined with an appropriate third drug, the correct answer is (D).",
