      "answerText": "(C) Normal light and accommodation reflex",
      "explanation": "In patients with diabetes mellitus, third cranial nerve (oculomotor nerve) palsy is commonly caused by microvascular ischemia affecting the central core of the nerve. The oculomotor nerve contains motor fibers centrally and parasympathetic (pupillary) fibers peripherally.\nIn diabetic third nerve palsy, the central motor fibers are affected first, leading to ptosis and limitation of eye movements (ophthalmoplegia). However, the peripheral parasympathetic fibers that control the pupil are usually spared because they receive a richer blood supply.\nAs a result, the pupil remains normal, and both the light reflex and accommodation reflex are preserved in the early stages. This phenomenon is known as pupil-sparing third nerve palsy, which is characteristic of diabetic ischemic neuropathy.\nIn contrast, compressive lesions (such as a posterior communicating artery aneurysm) typically affect the peripheral parasympathetic fibers first, leading to an abnormal light reflex.\nTherefore, the earliest clinical finding is (C) Normal light and accommodation reflex.",
