      "correct": "A",
      "answerText": "(A) 12",
      "explanation": "Body Mass Index (BMI) is a simple measure used to assess body weight relative to height and is calculated as weight in kilograms divided by height in meters squared (kg/m²). In adult men, a normal BMI ranges from 18.5 to 24.9. A BMI below 18.5 is considered underweight, and values below 16 indicate severe malnutrition. When BMI falls to extremely low levels such as 12, it is considered life-threatening or “lethal.”\nAt a BMI of around 12, the body has critically low fat and muscle stores. This leads to severe protein–energy malnutrition, weakened immunity, electrolyte imbalance, cardiac arrhythmias, hypotension, hypothermia, and multi-organ dysfunction. The heart muscle becomes weak, increasing the risk of sudden cardiac death. Such low BMI levels are commonly seen in advanced anorexia nervosa or prolonged starvation and are associated with very high mortality rates.\nIn contrast, BMI values such as 13 or 14 are also extremely dangerous but may not always be immediately fatal with urgent medical intervention. Therefore, a BMI of 12 is considered the most lethal among the given options.",
