      "explanation": "The Net Reproduction Rate (NRR) is a demographic indicator that represents the average number of daughters that would be born to a woman (or a group of women) if she passed through her lifetime conforming to the age-specific fertility and mortality rates of a given year. An NRR of 1 signifies that each generation of mothers is producing exactly enough daughters to replace itself, leading to a stable population size over the long term (zero population growth). To achieve this replacement-level fertility, a certain proportion of couples in the reproductive age group must be using contraception. The Couple Protection Rate (CPR) is the percentage of eligible couples effectively protected against childbirth by one or another approved method of family planning. It has been estimated that a CPR of approximately 60% is required for a population to achieve an NRR of 1. This is a crucial target for national family planning programs aiming for population stabilization.",
