      "explanation": "NIKSHAY (derived from Ni for end and Kshay for TB) is a web-based and mobile-based health information management system developed and implemented by the Government of India for the National Tuberculosis Elimination Program (NTEP), formerly known as RNTCP. It was launched in 2012 to comprehensively monitor and manage TB patients and control program activities across the country. NIKSHAY serves as a unified interface for all stakeholders, including public and private healthcare providers, laboratories, and program managers. It is used for the mandatory notification of all TB cases, tracking patients from diagnosis through treatment completion, managing drug supplies, and monitoring treatment adherence. The system also integrates features for direct benefit transfers (Nikshay Poshan Yojana) to support patients' nutritional needs. It is a critical digital tool in India's strategy to eliminate tuberculosis by 2025, enabling real-time surveillance and improving the quality of patient care and program management.",
