      "explanation": "The Secondary Attack Rate (SAR) is a measure of the infectivity or contagiousness of a disease and is used to evaluate control measures. It is defined as the number of new cases of a disease that occur among the susceptible contacts of a known primary case, within one incubation period of the disease. The formula is :\nSAR = (Number of new cases among contacts / Total number of susceptible contacts) × 100.\nThis rate specifically measures the spread of a disease from the initial case (primary case) to those who were directly exposed to that case. It is a useful metric for investigating disease outbreaks in closed settings like households, schools, or barracks. The primary attack rate refers to the rate of disease among all those exposed during an outbreak. The case fatality rate is the proportion of cases that result in death.",
