      "correct": "A",
      "answerText": "(A) Calcium carbonate",
      "explanation": "The hardness of water is primarily caused by the presence of dissolved mineral salts of divalent cations, mainly calcium (Ca²⁺) and magnesium (Mg²⁺). Hardness is classified into two types : temporary and permanent. Temporary hardness is caused by the presence of bicarbonate salts of calcium and magnesium, such as calcium bicarbonate ( Ca(HCO₃)₂) and magnesium bicarbonate ( Mg(HCO₃)₂). This type of hardness can be removed by boiling the water, which causes the bicarbonates to precipitate as carbonates. Permanent hardness is caused by the presence of sulfates, chlorides, and nitrates of calcium and magnesium, such as calcium sulfate (CaSO₄). This type of hardness is not removed by boiling. Calcium carbonate (CaCO₃) itself is largely insoluble in pure water and therefore does not contribute significantly to the hardness of water. It is, in fact, the precipitate (limescale) that is formed when water with temporary hardness is boiled.",
