      "explanation": "Acute tonsillitis is an infection and inflammation of the palatine tonsils, which are located in the oropharynx between the palatoglossal and palatopharyngeal arches. The primary sensory nerve supply of the tonsils is the glossopharyngeal nerve (cranial nerve IX). This nerve provides sensory innervation to the tonsillar region, posterior one-third of the tongue, soft palate, and oropharynx.\nDuring acute tonsillitis, inflammation stimulates the glossopharyngeal nerve endings, leading to severe throat pain. The pain may radiate to the ear because the glossopharyngeal nerve also contributes to the sensory supply of the middle ear via the tympanic branch (Jacobson’s nerve). This explains the common symptom of referred otalgia in tonsillitis.\nThe trigeminal nerve mainly supplies the face and anterior oral cavity, the facial nerve is primarily motor to facial muscles, and the vagus nerve supplies the larynx and parts of the pharynx but is not the main sensory supply to the tonsils. Therefore, the glossopharyngeal nerve is most affected.",
