      "number": 192,
      "statement": "Where will be the placement location for the Audltory Brainstem lmplant?",
      "options": [
        "Scala tympani",
        "Recess of4th ventricle",
        "IAC",
        "back ofear"
      ],
      "correct": "B",
      "answerText": "(B) Recess of 4th ventricle",
      "explanation": "An Auditory Brainstem Implant (ABI) is used in patients who are not suitable candidates for a cochlear implant, particularly those with bilateral cochlear nerve damage, such as in neurofibromatosis type 2. Unlike a cochlear implant, which stimulates the cochlear nerve within the inner ear, an ABI directly stimulates the cochlear nuclei in the brainstem.\nThe implant electrode array is surgically placed in the lateral recess of the fourth ventricle, specifically over the cochlear nucleus on the surface of the brainstem. This location allows the device to bypass the damaged cochlea and auditory nerve and directly stimulate the central auditory pathway.\nThe scala tympani is the placement site for a cochlear implant, not a brainstem implant. The internal auditory canal (IAC) contains cranial nerves VII and VIII but is not the site of ABI electrode placement. “Back of ear” refers to the external processor placement, not the internal electrode.\nTherefore, the correct placement site for an Auditory Brainstem Implant is the recess of the fourth ventricle.",
