      "correct": "A",
      "answerText": "(A) Central retinal vein occlusion (CRVO)",
      "explanation": "Neovascular glaucoma (NVG) is a severe, secondary form of glaucoma characterized by the growth of new, abnormal blood vessels (neovascularization) over the iris (rubeosis iridis) and into the trabecular meshwork in the anterior chamber angle. These vessels obstruct the outflow of aqueous humor, leading to a rapid and often dramatic rise in intraocular pressure. The most common cause of NVG is severe, widespread retinal ischemia. The ischemic retina releases vasoproliferative factors, primarily Vascular Endothelial Growth Factor (VEGF), which stimulate the neovascularization. The two main underlying conditions that cause this level of ischemia are proliferative diabetic retinopathy and ischemic Central Retinal Vein Occlusion (CRVO). Following an ischemic CRVO, NVG typically develops after a latent period, classically around 3 months, or approximately 100 days, earning it the historical name 100-day glaucoma.",
