      "correct": "B",
      "answerText": "(B) Acute leukaemia",
      "explanation": "Roth spots are retinal hemorrhages that have a white or pale center. They are a non-specific finding observed on fundoscopic examination. The white center is thought to be composed of a fibrin-platelet plug, an accumulation of inflammatory cells, or aggregates of neoplastic cells. While classically associated with subacute bacterial endocarditis, Roth spots can be seen in a wide variety of systemic conditions. These include hematological disorders such as leukemia (both acute and chronic), pernicious anemia, and thrombocytopenia. They are also seen in collagen vascular diseases like lupus, systemic infections (endocarditis, HIV), and conditions causing anoxia or vascular damage, such as diabetic retinopathy and hypertension. Therefore, among the given options, Roth spots are a well-recognized manifestation of acute leukemia, where they may represent retinal hemorrhage with a central collection of leukemic blasts. Uveal melanoma is a primary eye tumor and does not cause Roth spots.",
