      "correct": "A",
      "answerText": "(A) Left medial rectus",
      "explanation": "Yoke muscles are pairs of extraocular muscles, one in each eye, that are the primary movers of the two eyes into a specific direction of gaze. According to Hering's law of equal innervation, when a voluntary command is sent to move the eyes, the yoke muscles in both eyes receive equal and simultaneous innervation to ensure that the movements are conjugate (coordinated). The right lateral rectus muscle is the primary abductor of the right eye, moving it to the right (dextroversion). To maintain conjugate gaze to the right, the left eye must adduct (move towards the nose). The muscle responsible for adducting the left eye is the left medial rectus. Therefore, the right lateral rectus and the left medial rectus form a yoke pair for movement of the eyes into right gaze.",
