      "explanation": "Astigmatism occurs when the eye has different refractive powers at different meridians. In simple astigmatism, one of the two principal meridians is emmetropic (in focus on the retina), while the other is either myopic or hyperopic. In Simple Myopic Astigmatism, one meridian focuses light perfectly on the retina, while the other meridian focuses light in front of the retina (myopic). The refractive correction for this would require only a cylindrical lens to correct the myopic meridian, with no spherical component needed for the emmetropic meridian. The prescription -1.00 DC X 180 degree represents a pure cylindrical correction of -1.00 diopter, which is the correct format for simple myopic astigmatism. A prescription with DS indicates a spherical correction (+1.00 DS is simple hyperopia, -1.00 DS is simple myopia). A prescription with both DS and DC (-1.00 DS-1.00 DC) represents compound myopic astigmatism.",
