      "number": 200,
      "statement": "A diabetic patient develops hypopyon two days after undergoing cataract surgery. What is the appropriate management?",
      "options": [
        "Intravitreal antibiotics",
        "Eye drops",
        "Surgery",
        "No treatment required"
      ],
