      "answerText": "(A) Intravitreal antibiotics",
      "explanation": "A diabetic patient developing hypopyon two days after cataract surgery is highly suggestive of acute postoperative endophthalmitis, a vision-threatening emergency. It typically presents within a few days of surgery with pain, decreased vision, redness, lid edema, and hypopyon (pus in the anterior chamber).\nImmediate management is critical to prevent permanent visual loss. The standard treatment is urgent intravitreal broad-spectrum antibiotics, commonly vancomycin (for gram-positive coverage) and ceftazidime (for gram-negative coverage), after obtaining a vitreous sample for culture and sensitivity.\nTopical eye drops alone (Option B) are insufficient because the infection involves the vitreous cavity. Surgery (Option C), specifically pars plana vitrectomy, may be required in severe cases or when vision is only light perception, but the first essential step is intravitreal antibiotics. No treatment (Option D) is inappropriate and dangerous.\nTherefore, the most appropriate immediate management is (A) Intravitreal antibiotics.",
