      "number": 201,
      "statement": "According to the ISNT rule, which part of the neuroretinal rim is the thinnest?",
      "options": [
        "Inferior",
        "Superior",
        "Temporal",
        "Medial"
      ],
      "correct": "C",
      "answerText": "(C) Temporal",
      "explanation": "The ISNT rule describes the normal configuration of the neuroretinal rim thickness in a healthy optic disc. According to this rule, the rim thickness follows the order:\nI > S > N > T\n(Inferior > Superior > Nasal > Temporal)\nThis means the inferior rim is the thickest, followed by the superior rim, then the nasal rim, and the temporal rim is the thinnest.\nThe ISNT rule is clinically important in glaucoma evaluation. In glaucomatous optic neuropathy, this pattern is often disrupted, with early thinning typically occurring in the inferior and superior regions. If the rim does not follow the ISNT configuration, glaucoma should be suspected.\nTherefore, according to the ISNT rule, the thinnest part of the neuroretinal rim is the (C) Temporal rim.",
