      "explanation": "Fluid resuscitation in burn patients is calculated using the Parkland formula, which is:\n4 mL × body weight (kg) × % Total Body Surface Area (TBSA) burned\nFor this patient:\n4 mL × 50 kg × 40 = 8000 mL (8 litres) in the first 24 hours.\nAccording to the Parkland protocol:\nHalf of the total fluid is given in the first 8 hours (from the time of burn injury).\nThe remaining half is administered over the next 16 hours.\nSo, half of 8 litres = 4 litres in the first 8 hours.\nTherefore, the correct answer is (B) 4 litres.\nUrine output (target: 0.5–1 mL/kg/hour in adults) is closely monitored to adjust fluid therapy. Adequate resuscitation is essential to prevent burn shock and maintain organ perfusion.",
