      "correct": "B",
      "answerText": "(B) Greater auricular nerve",
      "explanation": "The image shows marked thickening of a nerve in the head and neck region, a classic sign of leprosy (Hansen's disease). The nerve shown is the greater auricular nerve. This is a sensory nerve that arises from the cervical plexus (C2, C3) and ascends vertically over the sternocleidomastoid muscle towards the ear. It supplies sensation to the skin over the angle of the jaw, the parotid gland, and a large part of the auricle (ear). The greater auricular nerve is one of the most commonly affected peripheral nerves in leprosy, along with the ulnar and common peroneal nerves. Its superficial course makes it easily visible and palpable when it becomes thickened due to the inflammatory and granulomatous infiltration caused by Mycobacterium leprae. Thickening of this nerve, often associated with loss of sensation in its distribution, is a cardinal sign of leprosy.",
