      "correct": "B",
      "answerText": "(B) Continuous lesion visualized in endoscopy",
      "explanation": "Crohn's disease is a type of inflammatory bowel disease that can affect any part of the gastrointestinal tract from the mouth to the anus. One of its hallmark features is the discontinuous nature of the inflammation, which is described as skip lesions. This means there are areas of active inflammation separated by segments of normal-appearing mucosa. Therefore, the statement that a continuous lesion is visualized on endoscopy is not true and is, in fact, the characteristic pattern of ulcerative colitis, where inflammation typically starts in the rectum and extends proximally in a continuous and circumferential manner. In Crohn's disease, the rectum is often spared (A). Histological examination frequently reveals non-caseating granulomas (C), another hallmark of the disease. The combination of deep linear ulcers and transmural inflammation with submucosal edema creates a nodular appearance of the mucosa on endoscopy or barium studies, which is described as a cobblestone appearance (D).",
