      "explanation": "Tom Smith's arthritis is an eponym for a particularly destructive form of septic arthritis of the hip joint that occurs in infancy. It was described by the surgeon Thomas Smith in 1874. The condition is characterized by a rapid and often complete destruction of the femoral head. In infants, the blood supply to the femoral head epiphysis passes through the joint capsule. An infection in the hip joint can cause a septic effusion that rapidly increases the intra-articular pressure. This pressure can compress the blood vessels, leading to avascular necrosis (death) of the femoral head. The infection can also directly destroy the cartilage. Because the femoral head in infants is largely cartilaginous, it can be completely destroyed by this process, leading to a pathological dislocation of the hip and severe long-term disability. This condition is an absolute surgical emergency requiring immediate drainage of the joint.",
