      "explanation": "In the given hysterosalpingogram (HSG) image, the uterine cavity appears elongated and curved to one side, with visualization of only a single fallopian tube. The cavity is narrow and banana-shaped rather than having two symmetrical horns.\nA unicornuate uterus results from incomplete development of one Müllerian duct. As a result, only one half of the uterus forms properly, producing a single uterine horn and usually one functional fallopian tube. On HSG, it characteristically shows a single, laterally placed uterine cavity with one-sided tubal filling.\nThis differs from:\n1. Septate uterus – Normal external uterine contour with internal septum dividing the cavity.\n2. Uterus didelphys – Two completely separate uterine cavities and cervices.\n3. Bicornuate uterus – Two uterine horns with a central indentation, giving a heart-shaped appearance.\nSince the image shows a single uterine cavity and unilateral tubal filling, the condition is most consistent with a unicornuate uterus",
