      "explanation": "Iodine is an essential micronutrient required for the synthesis of thyroid hormones, which are critical for regulating metabolism and for the normal growth and development of the brain and nervous system. The requirement for iodine increases significantly during pregnancy and lactation to meet the needs of both the mother and the developing fetus or newborn. The Recommended Dietary Allowance (RDA) for iodine in non-pregnant adult women is 150 µg/day. During pregnancy, this increases to 220 µg/day to support fetal neurodevelopment. The requirement is highest during lactation, as a significant amount of iodine is secreted into breast milk to provide for the infant's needs. The World Health Organization (WHO) and other health bodies recommend an iodine intake of 250 µg/day for lactating women. This ensures that the mother remains euthyroid while also providing sufficient iodine to the breastfed infant for their own thyroid hormone production and brain development.",
