      "correct": "A",
      "answerText": "(A) Placenta previa",
      "explanation": "Postpartum hemorrhage (PPH) is classified as primary or secondary. Primary PPH occurs within the first 24 hours after delivery. Secondary PPH is defined as excessive vaginal bleeding that occurs between 24 hours and 12 weeks postpartum. The most common cause of secondary PPH is subinvolution of the placental site, which is often associated with retained placental fragments or membranes. The second most common cause is uterine infection, such as endometritis. Other less common causes include the breakdown of uterine incision scars, placental site polyps, or underlying congenital bleeding disorders. Placenta previa, a condition where the placenta implants over or near the cervical os, is a major cause of antepartum hemorrhage (bleeding before delivery) and is a significant risk factor for primary PPH due to poor uterine contractility at the lower segment after placental separation. It is not a direct cause of secondary PPH.",
