      "explanation": "The quadruple screen, or quad test, is a maternal blood screening test performed during the second trimester of pregnancy to assess the risk of certain chromosomal abnormalities and neural tube defects in the fetus. The test measures the levels of four specific substances in the mother's blood : alpha-fetoprotein (AFP), human chorionic gonadotropin (hCG), unconjugated estriol (uE3), and inhibin A. The results of these four markers, combined with the mother's age and other factors, are used to calculate a risk score for Down syndrome (trisomy 21), Edwards syndrome (trisomy 18), and open neural tube defects (like spina bifida). The optimal time window for performing the quadruple test to ensure the most accurate results is between 15 and 20 weeks of gestation. The ideal time within this window is often cited as 16 to 18 weeks. Performing the test outside this timeframe can lead to less reliable results.",
