      "explanation": "Shoulder dystocia is an obstetric emergency where the anterior shoulder of the fetus becomes impacted behind the mother's pubic symphysis after the delivery of the head. A sequence of maneuvers is used to resolve it. The first maneuver is the McRoberts maneuver (A), which involves hyperflexion of the mother's hips onto her abdomen. This flattens the sacral promontory and rotates the pubic symphysis, often creating enough space for the shoulder to deliver. If this maneuver alone is unsuccessful, the next step is to apply suprapubic pressure. An assistant applies firm, downward pressure on the maternal abdomen just above the pubic bone, in an attempt to adduct the fetal shoulder and push it under the symphysis. The McRoberts maneuver and suprapubic pressure are often performed simultaneously. Internal rotational maneuvers, such as the Rubin or Wood's screw maneuver (C), are performed next if the initial steps fail. An emergency C-section (D) is not possible at this stage as the head is already delivered.",
