      "correct": "A",
      "answerText": "(A) Previous history of manual removal of placenta",
      "explanation": "A high-risk pregnancy is one in which the mother or the fetus has an increased risk of morbidity or mortality before, during, or after delivery. Conditions like pre-existing or gestational diabetes (C), severe anemia (B), and significant maternal obesity (D) are all well-established risk factors that classify a pregnancy as high-risk. These conditions can lead to numerous complications, including pre-eclampsia, fetal growth abnormalities, preterm birth, and delivery complications. In contrast, a previous history of manual removal of the placenta is a risk factor for a retained placenta in a subsequent pregnancy, but it is not typically considered a factor that categorizes the entire pregnancy as high-risk from the outset, in the same way that a major medical condition like diabetes does. While it requires vigilance during the third stage of labor, it does not have the same level of systemic impact on the antepartum course as the other conditions listed.",
