      "correct": "B",
      "answerText": "(B) Atenolol",
      "explanation": "The management of hypertension in pre-eclampsia involves the use of antihypertensive agents that are safe and effective during pregnancy. The commonly used and recommended first-line oral agents include the central alpha-2 agonist methyldopa (A) and the combined alpha- and beta-blocker labetalol (C). The calcium channel blocker nifedipine is also a first-line option. For hypertensive emergencies, intravenous labetalol and the direct vasodilator hydralazine (D) are used. However, atenolol (B), which is a beta-1 selective blocker, is generally avoided during pregnancy. Its use, particularly in the second and third trimesters, has been associated with an increased risk of fetal growth restriction (intrauterine growth restriction -IUGR) and low birth weight. Because of this potential adverse effect on fetal growth, other beta-blockers like labetalol are preferred, and atenolol is not a recommended choice for treating hypertension in pre-eclampsia.",
