      "correct": "D",
      "answerText": "(D) Kroener method",
      "explanation": "Fimbrectomy refers to a method of female sterilization in which the fimbrial end of the fallopian tube is surgically removed. This procedure is specifically known as the Kroener method. In this technique, the distal (fimbrial) portion of the fallopian tube is excised, thereby preventing the ovum from entering the tube and eliminating the possibility of fertilization. Since the fimbriae play a crucial role in capturing the ovulated egg from the ovary and guiding it into the fallopian tube, their removal effectively results in permanent contraception.\nThe Kroener method is considered a definitive sterilization procedure and is generally performed when permanent contraception is desired. Unlike other techniques such as the Irving method, Uchida method, or Madlener technique—which involve ligation, resection, or burying segments of the fallopian tube—the Kroener method specifically targets and removes the fimbrial end. Because of this distinctive feature, fimbrectomy is synonymous with the Kroener method in gynecological surgical practice.",
