      "correct": "A",
      "answerText": "(A) Hot flushes",
      "explanation": "Hormone therapy (HT) is primarily indicated for the management of menopausal symptoms, especially vasomotor symptoms such as hot flushes and night sweats. These symptoms occur due to decreased estrogen levels during menopause, which affect the body’s thermoregulatory center in the hypothalamus. HT helps relieve these symptoms by replacing the deficient estrogen, thereby improving quality of life and sleep patterns in symptomatic women.\nHormone therapy is not indicated in women with breast cancer, as estrogen may stimulate hormone-sensitive tumor growth. It is also not routinely used to treat endometriosis in menopausal women unless under specific specialist guidance. Abnormal uterine bleeding requires proper evaluation to determine the underlying cause and is not itself an indication for HT.\nTherefore, the most appropriate and common indication for hormone therapy in menopausal women is the treatment of bothersome hot flushes.",
