      "answerText": "(B) 46 XX Ovotestis",
      "explanation": "True hermaphroditism, now more appropriately termed ovotesticular disorder of sex development (DSD), is a rare condition in which an individual has both ovarian and testicular tissue. This may be present as an ovotestis (a single gonad containing both ovarian and testicular tissue) or as one ovary and one testis.\nThe most common karyotype seen in individuals with ovotesticular DSD is 46,XX. Despite having a typical female chromosomal pattern, these individuals develop both types of gonadal tissue. The presence of testicular tissue may be due to translocation of the SRY gene or other genetic variations influencing sex differentiation.\nOption (A), 45,XO, is associated with Turner syndrome and streak gonads. Option (C), 47,XXY, is associated with Klinefelter syndrome. Option (D), 47,XX, is not a recognized standard karyotype.\nTherefore, the karyotype most commonly linked with true hermaphroditism is 46,XX with ovotestis formation.",
