      "answerText": "(B) Female pseudohermaphroditism",
      "explanation": "Congenital adrenal hyperplasia (CAH) is a group of inherited disorders caused by enzyme deficiencies in cortisol synthesis, most commonly 21-hydroxylase deficiency. This enzyme defect leads to decreased cortisol production and a compensatory increase in adrenocorticotropic hormone (ACTH), resulting in adrenal hyperplasia and excess androgen production.\nIn genetic females (46,XX), the excess androgens cause varying degrees of virilization of the external genitalia, such as clitoromegaly and labioscrotal fusion, while the internal reproductive organs (uterus, fallopian tubes, and ovaries) remain female. This condition is therefore termed female pseudohermaphroditism, meaning the chromosomal and gonadal sex is female, but the external genitalia are masculinized.\nMale pseudohermaphroditism involves undervirilization in 46,XY individuals and is not typically caused by CAH. The other options are not standard classifications.\nThus, CAH is classically associated with female pseudohermaphroditism.",
