    {
      "number": 265,
      "statement": "Which ligament is primarily responsible for maintaining the anteverted position of the uterus?",
      "options": [
        "Cardinal ligament",
        "Uterosacral ligament",
        "Pubocervical ligament",
        "Round ligament"
      ],
      "correct": "D",
      "answerText": "(D) Round ligament",
      "explanation": "The uterus normally lies in an anteverted and anteflexed position, meaning it tilts forward over the urinary bladder. The maintenance of this forward tilt (anteversion) is mainly supported by the round ligaments of the uterus.\nThe round ligaments arise from the uterine horns, pass laterally within the broad ligament, traverse the inguinal canal, and insert into the labia majora. Their forward pull helps keep the uterus tilted anteriorly.\nThe cardinal (transverse cervical) ligaments provide lateral support to the cervix and help prevent uterine prolapse. The uterosacral ligaments support the uterus posteriorly and maintain its position within the pelvis. The pubocervical ligaments provide anterior support to the cervix and bladder.\nAlthough these ligaments contribute to overall uterine support, the round ligaments specifically help maintain anteversion. Therefore, the ligament responsible for maintaining the anteverted position of the uterus is the round ligament.",
      "pages": [
        681,
        745
      ]
    },
    {
      "number": 266,
      "statement": "Chronic or long-standing pelvic inflammatory disease can result in which of the following complications?",
      "options": [
        "Pyometra",
        "Uterine polyps",
        "Pseudopregnancy",
        "Cystic endometrial hyperplasia"
      ],
      "correct": "A",
      "answerText": "(A) Pyometra",
      "explanation": "Long-standing pelvic inflammation, particularly chronic pelvic inflammatory disease (PID), can cause persistent infection and damage to the upper genital tract. Over time, chronic inflammation may lead to scarring, obstruction of the cervical canal, and impaired drainage of uterine secretions. When the outflow of uterine contents is blocked, pus may accumulate within the uterine cavity, resulting in a condition known as pyometra.\nPyometra is characterized by the collection of purulent material inside the uterus. It may present with lower abdominal pain, foul-smelling discharge, fever, or may sometimes be asymptomatic in elderly women. It is more commonly seen in postmenopausal women or in cases where cervical stenosis is present.\nUterine polyps and cystic endometrial hyperplasia are usually related to hormonal imbalance rather than infection. Pseudopregnancy is a psychological condition and is not caused by pelvic inflammation.\nTherefore, chronic pelvic inflammation may lead to pyometra.",
      "pages": [
        681,
        745
      ]
    }
