      "number": 277,
      "statement": "Which contrast dye is preferred for diagnosing esophageal perforation?",
      "options": [
        "lohexol",
        "Barium sulphate",
        "Gadolinium",
        "Lipiodol"
      ],
      "correct": "A",
      "answerText": "(A) lohexol",
      "explanation": "In suspected esophageal perforation, a water-soluble contrast agent is used initially to confirm the diagnosis. Iohexol is a non-ionic, water-soluble iodinated contrast medium commonly used for this purpose. It is preferred because if leakage occurs into the mediastinum or pleural cavity, it causes much less inflammatory reaction compared to barium.\nBarium sulphate, although excellent for outlining mucosal detail, is contraindicated in suspected perforation because extravasated barium can cause severe mediastinitis and fibrosis if it leaks outside the esophagus.\nGadolinium is used primarily as a contrast agent in MRI studies and is not used for evaluating esophageal perforation. Lipiodol is an oil-based contrast medium and is not routinely used for this indication.\nTherefore, in cases of suspected esophageal perforation, a water-soluble contrast such as iohexol is the dye of choice.",
      "pages": [
        683,
        752
      ]
