      "correct": "C",
      "answerText": "(C) CT-guided HSG",
      "explanation": "The evaluation of congenital uterine anomalies requires imaging techniques that can clearly delineate both the internal (endometrial cavity) and external (serosal) contour of the uterus. Ultrasound (USG), particularly 3D ultrasound, is an excellent, non-invasive initial tool. Hysterosalpingography (HSG) is a fluoroscopic procedure that uses contrast dye to outline the uterine cavity and fallopian tubes, effectively showing the internal contour but not the external fundal shape. Magnetic Resonance Imaging (MRI) is considered the gold standard as it provides superior soft tissue contrast and multiplanar imaging, allowing for a detailed and accurate classification of the anomaly by showing both internal and external uterine morphology without radiation exposure. MRI can be used alongside HSG concepts. However, Computed Tomography (CT) provides poor soft tissue resolution of the uterine zonal anatomy and involves significant ionizing radiation exposure, making it unsuitable and not a standard modality for the primary diagnosis of congenital uterine anomalies. A CT-guided HSG is not a recognized or utilized procedure for this purpose.",
      "pages": [
        683,
        752
      ]
