      "correct": "A",
      "answerText": "(A) MRI needed to assess hemorrhage.",
      "explanation": "In acute head injury, the investigation of choice to assess intracranial hemorrhage is a non-contrast CT scan, not MRI. CT scan is rapid, widely available, and highly sensitive for detecting acute bleeding, skull fractures, and mass effect. MRI is more useful for detecting subtle brain injuries such as diffuse axonal injury, small contusions, or subacute and chronic lesions, but it is not the first-line imaging modality in emergency settings.\n1. Option (B) is correct because the Glasgow Coma Scale (GCS) is an important clinical tool used to assess the severity of head injury and helps predict prognosis.\n2. Option (C) is also correct, as some small hematomas without significant mass effect or neurological deterioration can be managed conservatively with close monitoring.\nTherefore, the incorrect statement is that MRI is needed to assess hemorrhage.",
