      "correct": "D",
      "answerText": "(D) Neurogenic tumor",
      "explanation": "The mediastinum is anatomically divided into anterior, middle, and posterior compartments. The anterior mediastinum commonly contains structures such as the thymus, lymph nodes, fat, and ectopic thyroid tissue. Therefore, tumors typically seen in the anterior mediastinum include:\n1. Thymoma (arising from the thymus)\n2. Lymphoma\n3. Thyroid tumors (especially substernal or retrosternal goiter)\nThese are often remembered as part of the classic “4 Ts” of anterior mediastinal masses: Thymoma, Thyroid tumor, Teratoma, and “Terrible” lymphoma.\nIn contrast, neurogenic tumors—such as schwannomas and neurofibromas—arise from nerve sheaths and are most commonly located in the posterior mediastinum, where the sympathetic chain and intercostal nerves are situated.\nTherefore, neurogenic tumors are not typically found in the anterior mediastinum, making option (D) the correct answer.",
